import {createSurface} from './surface.js';
const cache=new WeakMap();
export function paintedImage(image,strokes,revision=''){if(!strokes?.length)return image;const signature=revision+JSON.stringify(strokes),old=cache.get(image);if(old?.signature===signature)return old.canvas;const scale=Math.min(1,3072/Math.max(image.width,image.height)),w=Math.round(image.width*scale),h=Math.round(image.height*scale),baseKey=revision+JSON.stringify(strokes.slice(0,-1));let base;if(old?.baseKey===baseKey)base=old.base;else{base=createSurface(w,h);const bx=base.getContext('2d');if(old?.signature===baseKey)bx.drawImage(old.canvas,0,0);else{bx.drawImage(image,0,0,w,h);for(const z of strokes.slice(0,-1))paintStroke(base,z);}}const c=createSurface(w,h);c.getContext('2d').drawImage(base,0,0);paintStroke(c,strokes.at(-1));cache.set(image,{signature,canvas:c,baseKey,base});return c;}
export function paintStroke(c,z){const w=c.width,h=c.height,mask=createSurface(w,h),mx=mask.getContext('2d'),r=Math.max(.5,z.radius*Math.max(w,h));const stamp=(u,v)=>{const g=mx.createRadialGradient(u,v,r*Math.min(.999,z.hardness),u,v,r);g.addColorStop(0,'white');g.addColorStop(1,'transparent');mx.fillStyle=g;mx.fillRect(u-r,v-r,r*2,r*2);};let last=null;for(const p of z.points){const at=[p.x*w,p.y*h];if(last){const n=Math.max(1,Math.ceil(Math.hypot(at[0]-last[0],at[1]-last[1])/Math.max(.5,r*.25)));for(let i=1;i<=n;i++)stamp(last[0]+(at[0]-last[0])*i/n,last[1]+(at[1]-last[1])*i/n);}else stamp(...at);last=at;}
 if(z.selection){const a=z.selection;mx.globalCompositeOperation=a.invert?'destination-out':'destination-in';const sel=createSurface(w,h),sx=sel.getContext('2d');sx.fillStyle='white';const x=Math.min(a.x0,a.x1)*w,y=Math.min(a.y0,a.y1)*h,ww=Math.abs(a.x1-a.x0)*w,hh=Math.abs(a.y1-a.y0)*h;sx.beginPath();if(a.type==='ellipse')sx.ellipse(x+ww/2,y+hh/2,ww/2,hh/2,0,0,Math.PI*2);else sx.rect(x,y,ww,hh);sx.fill();mx.drawImage(sel,0,0);}
 const x=c.getContext('2d');x.save();x.globalAlpha=z.opacity;if(z.tool==='erase'){x.globalCompositeOperation='destination-out';x.drawImage(mask,0,0);}else{const overlay=createSurface(w,h),ox=overlay.getContext('2d');if(z.tool==='mosaic'){const block=Math.max(2,Math.round((z.block||.025)*Math.max(w,h))),small=createSurface(Math.ceil(w/block),Math.ceil(h/block));small.getContext('2d').drawImage(c,0,0,small.width,small.height);ox.imageSmoothingEnabled=false;ox.drawImage(small,0,0,w,h);}else{ox.fillStyle=z.color;ox.fillRect(0,0,w,h);}ox.globalCompositeOperation='destination-in';ox.drawImage(mask,0,0);x.drawImage(overlay,0,0);}x.restore();return c;}
